	(1001, 'thunderfury_spam', '%thunderfury_link의 위력은 *부정할 수 없지*!', 0, 0, '', 'Le pouvoir de %thunderfury_link est *indéniable*', 'Die Macht von %thunderfury_link ist *unbestreitbar*', '%thunderfury_link의 위력은 *부정할 수 없지*!', '', '', '', ''),
